@push('scripts')<script>const docs=@json($services->mapWithKeys(fn($s)=>[$s->id=>$s->requiredDocuments->map(fn($d)=>[$d->name_en,$d->name_gu])->values()]));const select=document.getElementById('service_id'),panel=document.getElementById('required-documents'),list=document.getElementById('required-documents-list');function draw(){let values=docs[select.value]||[];list.replaceChildren();values.forEach(v=>{let li=document.createElement('li');li.textContent=`${v[0]} (${v[1]})`;list.append(li)});panel.classList.toggle('d-none',!values.length)}select.addEventListener('change',draw);draw();</script>@endpush
